    /**
     * Exclude object from result
     *
     * @param   ComMigmasivo $comMigmasivo Object to remove from the list of results
     *
     * @return ComMigmasivoQuery The current query, for fluid interface
     */
    public function prune($comMigmasivo = null)
    {
        if ($comMigmasivo) {
            $this->addCond('pruneCond0', $this->getAliasedColName(ComMigmasivoPeer::COMMIGMASIVO_ID), $comMigmasivo->getCommigmasivoId(), Criteria::NOT_EQUAL);
            $this->addCond('pruneCond1', $this->getAliasedColName(ComMigmasivoPeer::COMLOTE_ID), $comMigmasivo->getComloteId(), Criteria::NOT_EQUAL);
            $this->combine(array('pruneCond0', 'pruneCond1'), Criteria::LOGICAL_OR);
        }

        return $this;
    }

